CSS = '''<style>
:root{color-scheme:dark}.stApp{background:radial-gradient(ellipse at 75% 0,#172b6533,transparent 55%),#090f23;color:#edf0f7}
h1,h2,h3{font-family:Inter,Segoe UI,sans-serif;letter-spacing:-.035em!important}h1{font-size:2.35rem!important;font-weight:650!important}
section[data-testid="stSidebar"]{background:#080e20;border-right:1px solid #253257}
section[data-testid="stSidebar"] h2{font-size:1.05rem!important}
.block-container{padding-top:4.5rem;max-width:1600px;padding-bottom:3rem}
[data-testid="stMetric"]{background:linear-gradient(130deg,#152347dd,#101a32);border:1px solid #293b64;padding:18px;border-radius:15px;min-height:110px}
[data-testid="stMetricLabel"]{color:#9da7ba;font-size:.82rem}[data-testid="stMetricValue"]{font-size:1.9rem;font-weight:600}
button{border-radius:8px!important}button[kind="primary"]{background:#6265ee;border-color:#8184ff}button:hover{border-color:#8184ff!important}
[data-testid="stExpander"]{border:1px solid #292e3a;border-radius:10px;background:#13161d}
.eyebrow{color:#9eabca;font-size:.72rem;font-weight:600;letter-spacing:.15em;text-transform:uppercase;margin-bottom:8px}
.hero{padding:23px 26px;border:1px solid #30354a;background:linear-gradient(115deg,#171c2f,#15171e 65%);border-radius:14px;margin:10px 0 24px}
.hero h2{font-size:1.6rem!important;margin:0}.hero p{color:#9faac0;font-size:.95rem;margin:7px 0 0}
.badge{display:inline-block;padding:5px 10px;border:1px solid #343c53;background:#1a2233;border-radius:6px;font-size:.72rem;color:#bac9ff;letter-spacing:.04em}
.taskbar{padding:16px 20px;border:1px solid #303543;border-radius:10px;background:#171a22;margin:12px 0}
.small{color:#97a2b7;font-size:.8rem}.brand{font-weight:700;font-size:1.2rem;letter-spacing:-.04em;padding:10px 0 20px}.brand span{color:#8c8aff}
.nodegrid{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:24px;background:radial-gradient(#272d3e 1px,transparent 1px);background-size:18px 18px;border-radius:12px;border:1px solid #2a2f3b}
.node{background:#191d28;border:1px solid #363f55;border-radius:10px;padding:16px 20px;min-width:150px;flex:1}.node strong{display:block;font-size:.95rem}.node small{display:block;color:#9ba6bb;font-size:.72rem;margin-top:5px}.node.done{border-color:#2b8069}.node.failed{border-color:#bb5065}.node.active{border-color:#6e70ff;box-shadow:0 0 22px #625eee16}.arrow{color:#6b7390;font-size:1.2rem}
.section-label{font-size:.8rem;color:#a5aec1;letter-spacing:.06em;text-transform:uppercase;margin:22px 0 10px}
.contract-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.contract-row span{border:1px solid #3a4e78;background:#1b2b4b;color:#c5d8ff;border-radius:6px;padding:5px 9px;font-size:.75rem}
.compare-summary{background:#111e37;border:1px solid #374e79;border-radius:10px;padding:14px 16px}.compare-summary>strong{font-size:1.4rem;color:#d3e3ff}.compare-summary.failed>strong{color:#ff8fa5}.compare-summary.recovered>strong{color:#ffd083}.compare-summary.done>strong{color:#66dfb5}.compare-facts{display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;margin-top:10px;font-size:.75rem;color:#a8bfdd}.compare-facts b{display:block;color:#edf5ff;font-size:.88rem}
.trace-schematic{display:flex;gap:10px;align-items:flex-start;flex-wrap:wrap;margin:16px 0 24px}.stage-route{flex:1;min-width:185px}.evidence-node{background:linear-gradient(135deg,#182744,#111c34);border:1px solid #445475;border-radius:12px;padding:18px;line-height:1.5}.evidence-node strong{display:block;font-size:1.05rem;margin:8px 0;color:#eef5ff}.evidence-node small{display:block;font-size:.8rem;color:#b5c6df}.evidence-node div{font-size:.9rem}.evidence-node.done{border-color:#39a784}.evidence-node.failed{border-color:#d25a73;background:#3a1c3433}.evidence-node.recovered{border-color:#dca642;background:#4b391d33}.evidence-node.active{border-color:#668dff}.stage-state{float:right;font-size:.66rem;font-weight:700;letter-spacing:.04em;color:#cbd9ef}.failed .stage-state{color:#ff99a9}.recovered .stage-state{color:#ffd382}.done .stage-state{color:#69deb9}.route-arrow{align-self:center;font-size:1.35rem;color:#8197bd}.recovery-connector{padding:7px 10px;color:#f0be62;font-size:.78rem}.trace-schematic.vertical{display:block}.vertical .stage-route{width:100%}.vertical .route-arrow{text-align:center;padding:6px}.io-snippet{color:#b9cbe5;font-size:.78rem;margin:12px 0 0!important}.io-snippet b{color:#d5e3f7}
.node-icon{display:inline-grid;place-items:center;width:32px;height:32px;border-radius:10px;background:#5475ff29;color:#a1b4ff;font-weight:700;margin-bottom:10px}.node.done .node-icon{background:#19bc8e26;color:#57e0b8}.node.failed .node-icon{background:#ef566626;color:#ff93a3}
.story{display:flex;align-items:center;gap:10px;padding:16px 0;flex-wrap:wrap}.story-step{flex:1;text-align:center;color:#7887a9;min-width:85px}.story-step span{display:grid;place-items:center;border:1px solid #354365;border-radius:50%;width:37px;height:37px;margin:0 auto 8px;font-size:1.1rem}.story-step small{display:block}.story-step.done{color:#6ee3be}.story-step.done span{border-color:#329b80;background:#123f3f}
.story-step.failed{color:#ff899c}.story-step.failed span{border-color:#b35069;background:#642b4233}
.welcome{padding:22px 26px;background:linear-gradient(120deg,#143d91aa,#1c2456aa);border:1px solid #3159a5;border-radius:18px;margin:12px 0 20px}.welcome h2{font-size:1.6rem!important;margin:0}.welcome p{color:#b9c8e4;max-width:680px;margin:8px 0 0}.statusline{font-size:.78rem;color:#93a9cb;margin:6px 0 12px}.step-label{color:#9ab8ff;font-size:.8rem;font-weight:600;letter-spacing:.06em;margin-top:15px}.result-good{border-color:#329b80!important}
@media(max-width:800px){.block-container{padding:1rem}.nodegrid{padding:12px}.node{min-width:120px}}
</style>'''
